def fibonacci(n):
    """Calculates the n-th Fibonacci number (F_1=1, F_2=1)."""
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

